"""Layer 15 MLP neuron 3072 (the down_proj component p-82af68dd@100000/layers.15.mlp.down_proj:3072).

This component is essentially one hidden unit of the MLP: its input vector is ~0.90 on
hidden unit 3072. Its activation is mostly small, with a negative tail. The tail sits where
the model is at a clause boundary that a main clause is about to follow:

  * the comma that closes an introductory clause ("If you are ever in town[,] ...",
    "As soon as you remove this ambiguity[,] ...", "如果……[，]"): strongest, about -1.6;
  * a question mark that ends a question: about -1.8;
  * "then" / "就" / "那就" / "则" starting the consequence of a condition: about -1.4;
  * other commas: mildly negative, about -0.2;
  * subject pronouns and auxiliaries ("I", "we", "you", "is", "will", "can"): slightly
    negative, about -0.15;
  * everything else: 0.

The program tracks the current sentence (reset at sentence ends, newlines and document
starts) and asks whether it opened with a subordinating word and has no comma yet.
The values are rough conditional means and regression weights fitted on about 390k
training tokens. On the eval rows the program explains about 3% of the variance
(Pearson r about 0.17), and its effect on the output is about the same as switching the
component off. The rest is diffuse and depends on context that a token rule cannot see:
a token-and-previous-token lookup reaches only about 5% in the same sample.
"""

import re

READS = ()

SENTENCE_END = {".", "!", "?", "。", "！", "？", ";"}
QUESTION_MARKS = {"?", "？", "?\n", "?\n\n"}
CONSEQUENCE_WORDS = {"then", " then", "Then", " Then", "就", "那就", "则"}
MAIN_CLAUSE_WORDS = {"is", " is", " will", " can", " would", " we", " I", " you", " it", " they"}
COMMAS = {",", "，"}
INTRO_EN = re.compile(
    r"^\s*(if|when|as|once|although|though|because|since|while|unless|until|after|before"
    r"|with|without|to|in|for|during|whether|given|upon|by)\b",
    re.I,
)
INTRO_ZH = ("如果", "若", "假如", "要是", "当", "因为", "虽然", "一旦", "即使", "尽管", "只要", "只有", "如若", "既然", "由于", "在")


def _opens_with_intro(text):
    """True if the sentence so far opens with a subordinating word."""
    return bool(INTRO_EN.match(text)) or text.lstrip().startswith(INTRO_ZH)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    new_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]
    # carry: (opening words of the current sentence, whether it has had a comma yet)
    head, comma_seen = ("", False) if (carry is None or new_doc) else carry
    bare = token.strip()

    if token in COMMAS:
        if comma_seen:
            value = -0.2  # a later comma in the sentence
        elif _opens_with_intro(head):
            value = -1.6  # comma closing an introductory clause; main clause follows
        else:
            value = -0.2
    elif token in QUESTION_MARKS or bare in QUESTION_MARKS:
        value = -1.8  # end of a question; an answer follows
    elif token in CONSEQUENCE_WORDS or bare in CONSEQUENCE_WORDS:
        value = -1.4  # consequence of a condition
    elif token in MAIN_CLAUSE_WORDS or bare in MAIN_CLAUSE_WORDS:
        value = -0.15
    else:
        value = 0.0

    if "\n" in token or bare in SENTENCE_END:
        carry = ("", False)
    else:
        carry = ((head + token)[:60], comma_seen or token in COMMAS)
    return carry, float(value)

"""Layer 15 MLP down-projection, component 3080: a "past era / years in the 1800s-1900s" feature.

What it responds to (measured on training text):
- The decade and year digits of a year written in the 1800s or 1900s, e.g. the "5" and "6"
  of "1956". The third digit (decade) is strongest: "19" then 0-5 gives about +8, 6 about +6,
  7 about +4, 8 about +3.5, 9 about +2.5 (later decades weaker). The fourth digit after "19"
  gives about +3, after "18" about +2.5. Years starting "20" are weak (about +0.7 and +0.3).
  The strongest cases are years in English prose ("a 1950 film", "from 1970 to"); the same digits
  inside code, page numbers or IDs are often negative, which this program cannot see.
- A few era words: "vintage", "classic", "historic", "century", "decades", "antique", ... (+3).
- Common function words and punctuation sit slightly below zero (-0.12).
Everything else is 0.

The program is a set of hand-picked rules, not a fit of the model. It explains about 6% of the
activation's variance on training rows; most of the rest is diffuse context that no short rule captures.
"""

READS = ()

DIGITS = set("0123456789")

# Activation for the decade digit (third digit) of a year starting "19" or "18".
DECADE_19 = {"0": 7.0, "1": 7.0, "2": 8.0, "3": 8.0, "4": 9.0, "5": 8.0, "6": 6.0, "7": 4.0, "8": 3.5, "9": 2.5}
DECADE_18 = {"0": 0.2, "1": 1.0, "2": 1.0, "3": 1.0, "4": 2.0, "5": 2.0, "6": 3.0, "7": 3.0, "8": 5.0, "9": 4.5}

ERA_WORDS = {
    "vintage", "classic", "classical", "traditional", "historic", "historical", "century",
    "centuries", "decades", "retro", "victorian", "soviet", "antique", "antiques", "colonial",
    "old", "ancient", "medieval",
}

FUNCTION_WORDS = {
    ",", ".", "the", "of", "and", "a", "in", "to", "is", "for", "(", "that", "with", "on", "as",
    "by", "was", "it", "be", "at", "from", "an", "or",
}


def _digit_run(prefix):
    """The digits ending at the newest token, within its document, oldest first."""
    run = []
    last = prefix.document_ids[-1]
    i = len(prefix.token_strings) - 1
    while i >= 0 and prefix.document_ids[i] == last and prefix.token_strings[i] in DIGITS:
        run.append(prefix.token_strings[i])
        i -= 1
    return run[::-1]


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    value = 0.0
    if token in DIGITS:
        run = _digit_run(prefix)
        start = run[:2]
        if len(run) == 3 and start == ["1", "9"]:
            value = DECADE_19[run[2]]
        elif len(run) == 3 and start == ["1", "8"]:
            value = DECADE_18[run[2]]
        elif len(run) == 4 and start == ["1", "9"]:
            value = 3.0
        elif len(run) == 4 and start == ["1", "8"]:
            value = 2.5
        elif len(run) == 3 and start == ["2", "0"]:
            value = 0.7
        elif len(run) == 4 and start == ["2", "0"]:
            value = 0.3
    elif token.lower() in ERA_WORDS:
        value = 3.0
    elif token in FUNCTION_WORDS:
        value = -0.12
    return carry, value

"""Predicts the component's mean value on two tokens where it leans positive, else 0."""
READS = ()

MEAN_VALUE = {"<think>": 1.0, " may": 0.8}


def step(carry, prefix, upstream):
    return carry, MEAN_VALUE.get(prefix.token_strings[-1], 0.0)

"""Layer 15, MLP hidden unit 3090 (down_proj component 3090): a turn-boundary detector.

The component is almost exactly one MLP hidden unit of layer 15 (its value is about 1.4 times
that unit's). It is near zero on most tokens. Its variance is concentrated at the ends of
turns and lines, and its big dips come in dialogue, transcripts and forum threads:

  - 'assistant' right after a chat-turn marker <|im_start|> is strongly positive;
  - the line break that closes a chat turn (right after <|im_end|>) is strongly negative;
  - a line break that ends a line of dialogue (after ? ! or a closing quote) is negative,
    much more so once speaker titles (Mr., Ms., Dr., Professor) have appeared earlier;
  - other line breaks and sentence-final marks are weakly negative, more so in the same
    speaker-rich documents;
  - a speaker title itself is negative, and a label's colon is weakly positive.

The program counts speaker titles so far in each document (reset at each new document).
Constants are least-squares fits on training rows, rounded.
"""
import math
import re
from collections.abc import Mapping

READS: tuple[str, ...] = ()

TITLES = {"Mr", "Ms", "Mrs", "Dr", "DR", "Professor"}
SENTENCE_END = re.compile(r"\s*[.?!\"”’'。！？」)]+\s*")
DIALOGUE_END = re.compile(r"[?!\"”。！？]")


def step(carry, prefix, upstream: Mapping):
    titles = 0 if carry is None else carry
    if len(prefix.token_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        titles = 0
    t = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    scale = math.log1p(titles)
    if t.strip() in TITLES:
        titles += 1
    if t == "assistant" and prev == "<|im_start|>":
        value = 5.4
    elif "\n" in t and prev == "<|im_end|>":
        value = -4.3
    elif "\n" in t and DIALOGUE_END.search(t):
        value = -1.4 - 11.5 * scale
    elif "\n" in t:
        value = -0.2 - 2.6 * scale
    elif SENTENCE_END.fullmatch(t):
        value = -0.1 - 0.7 * scale
    elif t.strip() in TITLES:
        value = -2.3
    elif t == ":":
        value = 0.2
    else:
        value = 0.0
    return titles, value

"""Layer 15 MLP unit 3093 (down_proj component): a lexical sketch of its large values.

What it does. This component writes into the residual stream with the output of one MLP
unit of layer 15, scaled. Most of its activation is small and diffuse, and tokens alone
explain very little of it. Its large values sit on a few recognisable kinds of spot, and this
program predicts the mean activation at each kind:

  positive
    - "as" starting a clause after a comma (", as ..."): about +1.9
    - other "as", except in fixed phrases ("such as", "known as", "defined as", ...): about +0.65
    - reporter and journal abbreviations in citations ("U.S", "F.D", "S.E", "Science"): about +1.0
    - the end-of-text token: about +0.4
  negative
    - the tag name right after "</" (the "div" in "</div>", "script", "footer"): about -1.7
    - "!" and "..." (and ".!"): about -0.8
    - a ">" line break after markup: about -0.65

Everything else predicts 0. The values are group means fitted on training rows; the fit
explains about 1% of the variance, and no readable token rule does much better.
"""

READS: tuple[str, ...] = ()

CLAUSE_AS_AFTER = {",", ";", "("}
FIXED_AS_BEFORE = {" such", " known", " defined", " same", " are", " seen", " described"}
CITATION_ABBREVIATIONS = {".S", ".D", ".E", ".Ed", ".R", "Q", " Science", " Journal", " Pharmac"}
CLOSE_TAG_START = {"</", " </"}
ELLIPSIS_OR_BANG = {"!", "...", ".!"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    same_document = len(prefix.token_strings) > 1 and (
        prefix.document_ids[-2] == prefix.document_ids[-1]
    )
    before = prefix.token_strings[-2] if same_document else ""
    if token == " as":
        if before in CLAUSE_AS_AFTER:
            value = 1.9
        elif before in FIXED_AS_BEFORE:
            value = 0.0
        else:
            value = 0.65
    elif token == "<|endoftext|>":
        value = 0.4
    elif token in CITATION_ABBREVIATIONS:
        value = 1.0
    elif before in CLOSE_TAG_START:
        value = -1.7
    elif token in ELLIPSIS_OR_BANG:
        value = -0.8
    elif token == ">\n":
        value = -0.65
    else:
        value = 0.0
    return carry, value

"""Layer 15 MLP down-projection, component 3094 (mostly hidden unit 3094).

What it does, in plain terms: this component's activation is a weak, mostly
context-driven signal. Its only readable surface regularities are:
  * the first token of a document is essentially zero;
  * the second token of a document sits slightly positive;
  * a token that continues a split word (letters only, no leading space, e.g.
    "ulation" in "coag|ulation") is on average positive, with heavier positive
    tails;
  * a token that starts a new word (letters only, leading space) is slightly negative.
The program predicts those class means and nothing finer, so it captures only a
small share of the variance.
"""

READS = ()

FIRST_TOKEN = 0.0    # first token of a document
SECOND_TOKEN = 0.6   # second token of a document
WORD_PIECE = 0.19    # letters only, no leading space: continues a word
WORD_START = -0.05   # letters only, leading space: starts a word


def _is_word_piece(s):
    return s.isascii() and s.isalpha() and not s.startswith(" ")


def _is_word_start(s):
    return s.strip().isascii() and s.strip().isalpha() and s.startswith(" ")


def step(carry, prefix, upstream):
    # carry: number of tokens so far in the current document (None at a row's start)
    doc = prefix.document_ids
    if carry is None or len(doc) < 2 or doc[-1] != doc[-2]:
        n = 0
    else:
        n = carry
    s = prefix.token_strings[-1]
    if n == 0:
        value = FIRST_TOKEN
    elif n == 1:
        value = SECOND_TOKEN
    elif _is_word_piece(s):
        value = WORD_PIECE
    elif _is_word_start(s):
        value = WORD_START
    else:
        value = 0.0
    return n + 1, value

"""Layer 15, MLP hidden unit 3103: the component's output, as a word-class lookup.

The component is one MLP hidden unit's output (its down_proj column, so its activation
is that unit's value times the column norm). Its activation is mostly not explained by
any text rule: token identity explains well under 1% of its variance, and so does the
identity of the next token. This program keeps only the small tendencies seen on
16k training rows:
  - relative pronouns (which, who, whom, whose, that, qui, que, die, der) lean positive,
    the strongest tendency;
  - "from" leans mildly positive;
  - determiners and possessives (the, their, ...) lean very slightly positive;
  - object pronouns (it, them, ...) lean negative, as do closing punctuation and digits;
  - the first token of each document is 0 (the document's first position is special);
  - every other token sits near the component's mean, about -0.03.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

RELATIVE = {"which", "who", "whom", "whose", "that", "qui", "que", "die", "der"}
DETERMINER = {
    "the", "a", "an", "this", "these", "those",
    "his", "her", "its", "their", "our", "my", "your",
}
OBJECT = {"it", "them", "him", "me", "us"}
CLOSER = {",", ")", "]", '"', "”", ".", '",', "),"}


def word_value(token: str) -> float:
    """Mean activation for the token's word class, measured on training rows."""
    w = token.strip().lower()
    if w in RELATIVE:
        return 0.35
    if w == "from":
        return 0.14
    if w in DETERMINER:
        return 0.04
    if w in OBJECT:
        return -0.11
    if w in CLOSER or w.isdigit():
        return -0.04
    return -0.03


def step(carry, prefix, upstream: Mapping):
    """Carry (document, position in document); predict from the newest token's class."""
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pos = 0
    else:
        pos = carry[1] + 1
    value = 0.0 if pos == 0 else word_value(prefix.token_strings[-1])
    return (doc, pos), value

"""Explains layers.15.mlp.down_proj:3108, one rank-one piece of layer 15's MLP output.

The piece reads one MLP hidden unit (unit 3108 of layer 15), so its activation is that
unit's value times the piece's output norm. Its negative direction pushes the next token
toward "also", "likewise", "same", "too". The unit is far from zero almost only at a
document's closing <|endoftext|> token, where it is strongly negative after prose and
much less negative after code or maths. Everywhere else it is small and context-driven.

The program predicts that document-end signal:
  * at a closing <|endoftext|> (one not directly after another <|endoftext|>):
        -16 + 23 * (share of symbol-like tokens in the document's last 200 tokens)
    so prose endings sit near -16 and code or maths endings near 0;
  * on every other token: 0.
"""

import re

READS: tuple[str, ...] = ()

END = "<|endoftext|>"
SYMBOL_LIKE = re.compile(r"[^\w\s]+|\d+")  # punctuation, maths/code symbols, digits
WINDOW = 200
BASE, SLOPE = -16.0, 23.0


def symbol_share(strings):
    """Share of the strings that are punctuation, symbols or digits."""
    if not strings:
        return 0.0
    return sum(1 for s in strings if SYMBOL_LIKE.fullmatch(s.strip() or "a")) / len(strings)


def end_value(strings):
    """Predicted activation at the last token of `strings`, if that token closes a document."""
    if len(strings) < 2 or strings[-2] == END:
        return 0.0
    doc = []  # the document's tokens, newest first, up to WINDOW of them
    for s in reversed(strings[:-1]):
        if s == END or len(doc) >= WINDOW:
            break
        doc.append(s)
    return BASE + SLOPE * symbol_share(doc)


def step(carry, prefix, upstream):
    if prefix.token_strings[-1] != END:
        return carry, 0.0
    return carry, end_value(list(prefix.token_strings))


def main():
    """Show the predicted values for a prose ending and a code ending."""
    prose = ["The", " cat", " sat", " down", " again", " today", ".", END]
    code = ["x", " =", " {", "\n", " a", " +", " b", ";", "\n", "}", END]
    print("prose ending:", round(end_value(prose), 2))
    print("code ending:", round(end_value(code), 2))


if __name__ == "__main__":
    main()

"""Reason and purpose links: the word that introduces a "why" or "what for" phrase.

Component p-82af68dd@100000/layers.15.mlp.down_proj:3120 is a mostly quiet feature. Its
activation is large and positive on the word that opens a reason or purpose:
  - "to" in "due to" / "owing to" (the strongest case), and "to" after "attributed",
    "order", "desire", "wanting";
  - "of" in "because of" / "for the sake of", and "by" in "caused by", "driven by",
    "required by": a preposition that attaches a cause to its result;
  - "to" in "stood down to", "resigned to", "taking time off to", and "for" in "closed for
    repairs", "necessary for": a purpose or duration after a verb of leaving, closing or
    needing;
  - the reason words themselves: because, due, owing, 因为, 由于, 为了, weil, porque,
    wegen, за.
It is near zero elsewhere and slightly negative on plain function words ("of", "and",
"not", "which").

The program labels each token with the first group it fits. Each group returns its mean
activation on training rows. Most of the variance is context the program cannot see: the
activation spreads widely within every common word, so this explains only the strongest
positives. Its main value is the reading of what the component responds to.
"""

READS = ()  # this program reads no other component

# Words that state a reason outright, in several languages.
REASON_WORDS = {
    "because", "owing", "due", "因为", "因為", "由于", "由於", "为了", "為了", "因", "是因为",
    "weil", "porque", "wegen", "parce", "perchè", "за",
}
# Words after which a preposition attaches a cause or purpose to its result.
CAUSE_WORDS = {
    "due", "owing", "attributed", "caused", "driven", "influenced", "induced", "generated",
    "required", "explained", "dominated", "because", "sake", "consequence", "account",
    "order", "purposes", "purpose", "intended", "designed", "necessary", "desire", "wanting",
}
# Prepositions that open a purpose or cause phrase.
LINK_PREPOSITIONS = {"to", "for", "by", "of", "with", "as"}
# Purpose prepositions and conjunctions, which count more when a cue sits just before them.
PURPOSE_PREPOSITIONS = {"to", "for", "by", "with", "while", "as"}
# Words that set up a purpose: intent, need, use, leaving, taking a break, waiting, duration.
PURPOSE_CUES = {
    "trying", "tried", "try", "wanted", "want", "wanting", "desire", "used", "needed",
    "required", "taking", "take", "break", "away", "off", "leave", "left", "resigned",
    "waiting", "home", "returned", "allow", "allowed", "sold", "stopped", "closed", "down",
    "caused", "pursue", "focus", "concentrate", "order",
}
# Plain function words that sit slightly below zero.
PLAIN_FUNCTION_WORDS = {"of", "and", "not", "which", "has", "will", "but", "that", "if", "have", "be"}

CUE_WINDOW = 6  # how many earlier tokens, in the same document, to look back over


def step(carry, prefix, upstream):
    # Only the newest CUE_WINDOW + 1 tokens matter, so read just those.
    t = len(prefix.token_strings) - 1
    cur = prefix.token_strings[t].strip().lower()
    window = []
    for i in range(max(0, t - CUE_WINDOW), t):
        if prefix.document_ids[i] == prefix.document_ids[t]:
            window.append(prefix.token_strings[i].strip().lower())
    prev = window[-1] if window else ""

    if cur == "to" and prev in {"due", "owing"}:
        value = 3.0
    elif cur in LINK_PREPOSITIONS and prev in CAUSE_WORDS:
        value = 1.1
    elif cur in REASON_WORDS:
        value = 1.2
    elif cur in PURPOSE_PREPOSITIONS:
        value = 0.55 if any(w in PURPOSE_CUES for w in window) else 0.26
    elif cur in PLAIN_FUNCTION_WORDS:
        value = -0.08
    else:
        value = 0.0
    return None, value

"""
Component 3121 of layers.15.mlp.down_proj reads the layer-15 MLP hidden unit 3121 almost
entirely (its read direction is 0.83 of its 1.05 norm on that unit; the rest is spread over
other units). Its activation is a dense, sign-varying signal (std about 0.45, with rare
spikes to +/-15) that token identity and word class explain only a little of. So this
program predicts just the consistent parts, and it predicts 0 everywhere else:

- On a coordinating word ("and", "or", "but", "also", "even") it is mildly positive; on
  hedges and restrictive particles ("maybe", "perhaps", "only", "just", "no", "too") it is
  mildly negative. These are word-level averages from training text.
- Right after a coordinator ("X and ___", "X or ___", "than ___") the next word is positive
  when it begins a predicate ("is", "would", "will", ...) and negative when it begins an
  argument ("the", "some", "of", "in", ...).
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

COORDINATORS = {" and", " or", " but", " nor", " yet", " than"}
POSITIVE_WORDS = {" and": 0.13, " or": 0.22, " but": 0.15, " also": 0.30, " even": 0.29}
NEGATIVE_WORDS = {
    " maybe": -0.48, " perhaps": -0.39, " only": -0.41, " just": -0.32,
    " no": -0.33, " too": -0.23, " less": -0.27, " much": -0.19,
}
PREDICATE_STARTS = {
    " is", " was", " are", " were", " be", " been", " has", " have", " had",
    " will", " would", " can", " could", " should", " may", " might", " must",
    " does", " did", " do",
}
ARGUMENT_STARTS = {
    " the", " a", " an", " this", " that", " these", " those", " some", " many",
    " most", " all", " each", " every", " both", " no", " any", " several",
    " of", " in", " to", " for", " with", " on", " at", " by", " from", " into",
    " through", " about", " over", " between",
}
PREDICATE_VALUE = 0.5
ARGUMENT_VALUE = -0.25


def step(carry, prefix, upstream: Mapping):
    tokens = prefix.token_strings
    docs = prefix.document_ids
    if len(tokens) < 2 or docs[-1] != docs[-2]:
        return carry, 0.0
    word = tokens[-1]
    if tokens[-2] in COORDINATORS:
        if word in PREDICATE_STARTS:
            return carry, PREDICATE_VALUE
        if word in ARGUMENT_STARTS:
            return carry, ARGUMENT_VALUE
    if word in POSITIVE_WORDS:
        return carry, POSITIVE_WORDS[word]
    return carry, NEGATIVE_WORDS.get(word, 0.0)

"""Consequence connectives: the component fires on words that introduce a conclusion
("so", "therefore", "thus", "hence", "consequently", "因此"), most strongly when they
start a sentence or follow a comma, and on the comma just after them."""

READS = ()

# typical activation for each connective word (lowercased, stripped of spaces)
CONNECTIVES = {
    "therefore": 5.0, "thus": 5.0, "hence": 5.0, "consequently": 4.8, "accordingly": 3.5,
    "因此": 5.9, "因而": 5.7, "所以": 5.5, "ですから": 5.1, "だから": 3.0, "なので": 2.7, "ので": 3.2,
    "从而": 1.6, "thereby": 1.6, "implies": 1.3, "implying": 2.2, "⇒": 2.0,
    "so": 3.5,
}
# words that end a clause, so a following "so" is a conclusion ("..., so") rather than "so good"
CLAUSE_END = {"", ",", ".", ";", "!", "?", ")", "),", ").", "and", "but", "But"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if word in CONNECTIVES:
        value = CONNECTIVES[word]
        if word == "so" and prev not in CLAUSE_END:
            value = 0.5
        return carry, value
    if word == "then" and prev == ",":
        return carry, 1.0
    if word == "means" and prev in {"this", "that", "which", "it"}:
        return carry, 3.0
    if word == "," and prev in CONNECTIVES:
        return carry, 0.8 * CONNECTIVES[prev]
    return carry, 0.0

"""Layer 15, MLP hidden unit 3132 (this component's activation), as a word-class rule.

What it does: the unit goes negative on words that set up a person or a group of people.
Strongest on adjectives that describe a person's age, skill, status or sex ("young", "older",
"experienced", "skilled", "female", "foreign"). Moderate on nationality adjectives ("American",
"British") and on quantifiers over people ("each", "many", "other", "those"). Weaker on articles
("a", "the", and Romance plural articles "les", "los"), and on a few Chinese words that modify
people (年轻, 一位, 各位, 的). Every other token sits near zero. The predicted value is the mean
activation of each class, measured on training text.

What it misses: this rule explains about 1% of the activation's variance. Most of the variation
is diffuse, depends on context that no word list captures, and is spread over common tokens
such as "the" and "a" (their activations range from about -8 to +3).
"""

PEOPLE = {"young", "younger", "old", "older", "-old", "-aged", "elderly", "experienced",
          "skilled", "qualified", "talented", "wealthy", "poor", "unnamed", "female", "male",
          "returning", "former", "foreign"}
NATIONS = {"american", "british", "irish", "french", "english", "european", "japanese",
           "chinese", "german", "italian", "spanish", "russian", "indian", "black", "white",
           "african", "canadian", "mexican"}
QUANTIFIERS = {"each", "every", "many", "most", "some", "other", "those", "two", "several",
               "few", "both"}
ARTICLES = {"a", "an", "the", "les", "los", "las", "der", "die", "des", "la", "le", "gli", "aux"}
CHINESE = {"年轻", "岁的", "漂亮", "颜值", "身材", "气质", "一位", "各位", "每个", "不少",
           "广大", "的", "の"}

# Mean activation of each class on training text
VALUE = {"people": -1.5, "nation": -0.8, "quantifier": -0.6, "article": -0.3, "chinese": -1.0}
CLASS_OF = {}
for _words, _name in [(PEOPLE, "people"), (NATIONS, "nation"), (QUANTIFIERS, "quantifier"),
                      (ARTICLES, "article"), (CHINESE, "chinese")]:
    for _w in _words:
        CLASS_OF[_w] = _name

READS = ()


def step(carry, prefix, upstream):
    """The activation at this position, from the newest token alone (no carried state)."""
    word = prefix.token_strings[-1].strip().lower()
    name = CLASS_OF.get(word)
    return carry, (VALUE[name] if name else -0.06)

"""A conclusion word ("so", "thus", "therefore", "hence", "then") pushes this component's activation
strongly negative; "Wait" and "Hmm" (self-correction) push it positive. The push fades within a
couple of tokens. Everything else is predicted as 0."""
READS = ()
DECAY = 0.45  # the effect is about halved on each following token
CONCLUDE = {"thus": -3.8, "therefore": -4.0, "hence": -3.8, "consequently": -2.6, "then": -1.1}
PIVOT = {"wait": 1.1, "hmm": 0.75}
CLAUSE_START = (",", ".", "", "and", "but")  # 'so' opening a clause, not 'do so' / 'is so'

def step(carry, prefix, upstream):
    value = 0.0 if carry is None else carry * DECAY
    word = prefix.token_strings[-1].strip().lower()
    before = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if word in CONCLUDE:
        value = CONCLUDE[word]
    elif word == "so" and (before[-1:] in (",", ".") or before in CLAUSE_START):
        value = -3.3
    elif word in PIVOT:
        value = PIVOT[word]
    return value, value
